import { useState, useCallback } from "react";
import type { HeadersFunction, LoaderFunctionArgs } from "react-router";
import { useLoaderData } from "react-router";
import { useAppBridge } from "@shopify/app-bridge-react";
import { authenticate } from "../shopify.server";
import { boundary } from "@shopify/shopify-app-react-router/server";
import {
  Page,
  Layout,
  Card,
  Tabs,
  FormLayout,
  TextField,
  Select,
  Checkbox,
  Button,
  Badge,
  Banner,
  Text,
  BlockStack,
  InlineStack,
  Divider,
} from "@shopify/polaris";

export const loader = async ({ request }: LoaderFunctionArgs) => {
  await authenticate.admin(request);

  return {
    currentPlan: "free",
  };
};

export default function Settings() {
  const { currentPlan } = useLoaderData<typeof loader>();
  const shopify = useAppBridge();

  const [selectedTab, setSelectedTab] = useState(0);

  // General Settings state
  const [defaultLanguage, setDefaultLanguage] = useState("en");
  const [showBranding, setShowBranding] = useState(true);
  const [attributionWindow, setAttributionWindow] = useState("7");
  const [tagPrefix, setTagPrefix] = useState("qs-");

  // Email Capture state
  const [collectEmails, setCollectEmails] = useState(true);
  const [emailHeadline, setEmailHeadline] = useState(
    "Almost there! Get your personalised results",
  );
  const [gdprConsentText, setGdprConsentText] = useState(
    "I agree to receive personalised recommendations by email.",
  );
  const [skipLinkText, setSkipLinkText] = useState(
    "Skip — show results anyway",
  );
  const [discountCode, setDiscountCode] = useState("");

  const handleTabChange = useCallback(
    (selectedTabIndex: number) => setSelectedTab(selectedTabIndex),
    [],
  );

  const handleSave = useCallback(() => {
    shopify.toast.show("Settings saved");
  }, [shopify]);

  const tabs = [
    { id: "general", content: "General Settings", panelID: "general-panel" },
    { id: "email", content: "Email Capture", panelID: "email-panel" },
    {
      id: "integrations",
      content: "Integrations",
      panelID: "integrations-panel",
    },
    { id: "plans", content: "Plans & Billing", panelID: "plans-panel" },
  ];

  const languageOptions = [
    { label: "English", value: "en" },
    { label: "French", value: "fr" },
    { label: "Spanish", value: "es" },
    { label: "German", value: "de" },
    { label: "Hindi", value: "hi" },
  ];

  const attributionOptions = [
    { label: "3 days", value: "3" },
    { label: "7 days (recommended)", value: "7" },
    { label: "14 days", value: "14" },
    { label: "30 days", value: "30" },
  ];

  const integrations = [
    {
      name: "Klaviyo",
      connected: true,
      description:
        "Sends quiz events, answer data, email captures to Klaviyo",
    },
    {
      name: "Omnisend",
      connected: false,
      description:
        "Posts quiz completion events for SMS/email automations",
    },
    {
      name: "Shopify Flow",
      connected: false,
      description: "Creates native 'Quiz Completed' trigger",
    },
    {
      name: "Webhooks",
      connected: false,
      description: "Sends data to any external URL via HTTP POST",
    },
  ];

  const plans = [
    {
      name: "Free",
      price: "$0/mo",
      completions: "100/month",
      features: [
        "1 quiz",
        "All question types",
        "Basic analytics",
        "Branding shown",
      ],
      isCurrent: currentPlan === "free",
      isPopular: false,
    },
    {
      name: "Starter",
      price: "$29/mo",
      completions: "Unlimited",
      features: [
        "5 quizzes",
        "Klaviyo + Webhooks",
        "Remove branding",
        "Advanced analytics",
        "Email capture",
      ],
      isCurrent: currentPlan === "starter",
      isPopular: true,
    },
    {
      name: "Pro",
      price: "$79/mo",
      completions: "Unlimited",
      features: [
        "Unlimited quizzes",
        "AI auto-mapping",
        "A/B testing",
        "Shopify Flow",
        "Priority support",
      ],
      isCurrent: currentPlan === "pro",
      isPopular: false,
    },
  ];

  const renderGeneralSettings = () => (
    <Layout>
      <Layout.Section>
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd">
              General Settings
            </Text>
            <FormLayout>
              <Select
                label="Default quiz language"
                options={languageOptions}
                value={defaultLanguage}
                onChange={setDefaultLanguage}
              />
              <Checkbox
                label="Show 'Powered by QuizSnap' branding"
                checked={showBranding}
                onChange={setShowBranding}
                helpText="Requires Starter plan to remove"
              />
              <Select
                label="Revenue attribution window"
                options={attributionOptions}
                value={attributionWindow}
                onChange={setAttributionWindow}
              />
              <TextField
                label="Customer tag prefix"
                value={tagPrefix}
                onChange={setTagPrefix}
                autoComplete="off"
                helpText={`Example: prefix '${tagPrefix}' produces tag '${tagPrefix}skin-type:oily'`}
              />
            </FormLayout>
            <InlineStack align="end">
              <Button variant="primary" onClick={handleSave}>
                Save
              </Button>
            </InlineStack>
          </BlockStack>
        </Card>
      </Layout.Section>
    </Layout>
  );

  const renderEmailCapture = () => (
    <Layout>
      <Layout.Section>
        <Card>
          <BlockStack gap="400">
            <Text as="h2" variant="headingMd">
              Email Capture
            </Text>
            <FormLayout>
              <Checkbox
                label="Collect emails before showing results"
                checked={collectEmails}
                onChange={setCollectEmails}
              />
              <TextField
                label="Email screen headline"
                value={emailHeadline}
                onChange={setEmailHeadline}
                autoComplete="off"
              />
              <TextField
                label="GDPR consent text"
                value={gdprConsentText}
                onChange={setGdprConsentText}
                autoComplete="off"
              />
              <TextField
                label="Skip link text"
                value={skipLinkText}
                onChange={setSkipLinkText}
                autoComplete="off"
              />
              <TextField
                label="Discount reveal on email capture"
                value={discountCode}
                onChange={setDiscountCode}
                autoComplete="off"
                placeholder="e.g. WELCOME10"
                helpText="Enter a discount code like WELCOME10 to reveal after email capture"
              />
            </FormLayout>
            <InlineStack align="end">
              <Button variant="primary" onClick={handleSave}>
                Save
              </Button>
            </InlineStack>
          </BlockStack>
        </Card>
      </Layout.Section>
    </Layout>
  );

  const renderIntegrations = () => (
    <Layout>
      <Layout.Section>
        <BlockStack gap="400">
          {integrations.map((integration) => (
            <Card key={integration.name}>
              <BlockStack gap="300">
                <InlineStack align="space-between" blockAlign="center">
                  <InlineStack gap="300" blockAlign="center">
                    <Text as="h3" variant="headingMd">
                      {integration.name}
                    </Text>
                    {integration.connected ? (
                      <Badge tone="success">Connected</Badge>
                    ) : (
                      <Badge>Not connected</Badge>
                    )}
                  </InlineStack>
                  <InlineStack gap="200">
                    {integration.connected ? (
                      <>
                        <Button>Configure</Button>
                        <Button tone="critical">Disconnect</Button>
                      </>
                    ) : (
                      <Button variant="primary">Connect</Button>
                    )}
                  </InlineStack>
                </InlineStack>
                <Text as="p" variant="bodyMd" tone="subdued">
                  {integration.description}
                </Text>
              </BlockStack>
            </Card>
          ))}
        </BlockStack>
      </Layout.Section>
    </Layout>
  );

  const renderPlans = () => (
    <Layout>
      {plans.map((plan) => (
        <Layout.Section key={plan.name} variant="oneThird">
          <Card>
            <BlockStack gap="400">
              <InlineStack gap="200" blockAlign="center">
                <Text as="h2" variant="headingLg">
                  {plan.name}
                </Text>
                {plan.isPopular && <Badge tone="info">Most popular</Badge>}
                {plan.isCurrent && <Badge>Current plan</Badge>}
              </InlineStack>
              <BlockStack gap="100">
                <Text as="p" variant="headingXl">
                  {plan.price}
                </Text>
                <Text as="p" variant="bodyMd" tone="subdued">
                  {plan.completions} completions
                </Text>
              </BlockStack>
              <Divider />
              <BlockStack gap="200">
                {plan.features.map((feature) => (
                  <Text as="p" variant="bodyMd" key={feature}>
                    {feature}
                  </Text>
                ))}
              </BlockStack>
              {plan.isCurrent ? (
                <Button disabled>Current plan</Button>
              ) : (
                <Button variant="primary">
                  {plan.price === "$0/mo" ? "Downgrade" : "Upgrade"}
                </Button>
              )}
            </BlockStack>
          </Card>
        </Layout.Section>
      ))}
    </Layout>
  );

  const tabContent = [
    renderGeneralSettings,
    renderEmailCapture,
    renderIntegrations,
    renderPlans,
  ];

  return (
    <Page title="Settings">
      <Layout>
        <Layout.Section>
          <Card padding="0">
            <Tabs tabs={tabs} selected={selectedTab} onSelect={handleTabChange}>
              <div style={{ padding: "16px" }}>{tabContent[selectedTab]()}</div>
            </Tabs>
          </Card>
        </Layout.Section>
      </Layout>
    </Page>
  );
}

export const headers: HeadersFunction = (headersArgs) => {
  return boundary.headers(headersArgs);
};
